"""Assemble an authorization-pending protocol; no sender or credentials."""
import json,pathlib,hashlib
from s22_ab import ROOT,VERSION
from failure_evo.contracts import atomic_json,fingerprint
OUT=ROOT/'reports/s22_action_preference_v1'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 selected=json.loads((OUT/'selected_checkpoints.json').read_text());scoring=json.loads((OUT/'scoring_manifest.json').read_text());worker=json.loads((OUT/'worker_acceptance.json').read_text())
 assert worker['status']=='PASS' and all(x['review_available'] for x in scoring['rows'])
 frozen=[json.loads((OUT/'frozen'/f'{i+1:02d}.json').read_text()) for i in range(len(selected))]
 for x,row in zip(frozen,worker['rows'][4:]):assert x['request_freeze']['checkpoint_hash']==row['checkpoint_sha256']
 input_max=sum(x['request_freeze']['arms'][a]['input_upper'] for x in frozen for a in ['A','B']);output_max=8192*2*len(selected)
 quote=dict(url='https://api-docs.deepseek.com/quick_start/pricing/',checked_date='2026-10-26',model='deepseek-flash',advertised_version='DeepSeek-V4.1-Flash-1017',peak_cache_miss_input_per_million=.3,peak_output_per_million=1.2,off_peak_discount_used=False,actual_invoice=None)
 atomic_json(OUT/'pricing_review.json',quote)
 dependencies=[ROOT/'scripts'/n for n in ['s22_ab.py','s22_audit.py','s22_freeze.py','s22_worker_acceptance.py','s22_scoring_manifest.py','run_workflow_v2.py','learn_reuse30.py','compare30_workflows.py']]+list((ROOT/'FlowEvo/src/failure_evo').glob('*.py'))
 dependencies += [pathlib.Path(worker['worker_manifest']['worker_script']),ROOT/'experiments/flowevo_taco_lcb_20261019/e3_s1_20261020/code/legal_suite.py',ROOT/'experiments/flowevo_taco_lcb_20261019/trusted_rgf_20261020/code/suite.py']
 datafiles=[OUT/'selected_checkpoints.json',OUT/'scoring_manifest.json',OUT/'pricing_review.json',OUT/'worker_acceptance.json',*sorted((OUT/'frozen').glob('*.json'))]
 protocol=dict(version=VERSION,status='FROZEN_DRY_RUN_AWAITING_EXPLICIT_API_AUTHORIZATION',source_commit='ede4b9b708040d67f5dab69afe77f50e3488a7d1',selection='First fully restorable/legal/preflightable checkpoint per audited task component; round-robin sorted dataset/difficulty/failure strata, chronological within strata; first 10; no branch outcomes used',tasks=selected,task_order=[r['task_id'] for r in selected],arm_order=[['A','B'] if i%2==0 else ['B','A'] for i in range(len(selected))],max_calls_per_branch=1,max_provider_requests=2*len(selected),model=quote['model'],advertised_model_version=quote['advertised_version'],temperature=0,thinking='disabled',reasoning_effort='none',output_limit=8192,input_limit=32768,frozen_wire_input_upper_total=input_max,output_upper_total=output_max,reasoning_expected=0,missing_reasoning_usage='NOT_REPORTED, never inferred actual zero',directional_quote_upper_usd=(input_max*.3+output_max*1.2)/1e6,persistent_reservation_rate_usd_per_million=1.2,frozen_wire_reservation_upper_usd=(input_max+output_max)*1.2/1e6,absolute_per_request_cap_reservation_usd=(32768+8192)*2*len(selected)*1.2/1e6,proposed_hard_usd=1,tool_calls_cap=1000,worker_wall_seconds_cap=12000,local_compute_currency=None,online_clock='fresh clock per branch, duration capped at min(600, recorded remaining_seconds); same restored counters before each branch',sealed_rule='Separate evaluator only after all online branch states locked; use scoring_manifest identities/hashes; no online access',continuation='No retry, no learning, no revised prompt, no new task. UNKNOWN stops Run without resend; known complete branch failures continue frozen order.',stops=['UNKNOWN provider outcome','hash/model/settings mismatch','data contamination','Worker/scorer failure','unrecoverable state','hard budget'],permitted_conclusions='RQ1 exploratory single-shot paired outcomes; RQ2 descriptive frozen-state association only; RQ3 NOT_STARTED',sources={str(p.relative_to(ROOT)):sha(p) for p in dependencies},artifacts={str(p.relative_to(ROOT)):sha(p) for p in datafiles},evaluator_sources=scoring['evaluator_sources'])
 protocol['protocol_hash']=fingerprint(protocol);atomic_json(OUT/'protocol.json',protocol);print(protocol['protocol_hash'],protocol['directional_quote_upper_usd'],protocol['frozen_wire_reservation_upper_usd'])
if __name__=='__main__':main()
